function longestRise(nums: number[]): number {
  const go = (i: number, last: number): number => {
    if (i === nums.length) return 0;
    let best = go(i + 1, last); // skip nums[i]
    if (nums[i] > last) best = Math.max(best, 1 + go(i + 1, nums[i]));
    return best;
  };
  return go(0, -Infinity);
}

