function longestRise(nums: number[]): number {
  const n = nums.length;
  const len = new Array<number>(n).fill(1);
  for (let i = 1; i < n; i++)
    for (let j = 0; j < i; j++)
      if (nums[j] < nums[i] && len[j] + 1 > len[i]) len[i] = len[j] + 1;
  return Math.max(...len);
}

